// DataSource holds a datasource
type DataSource struct {
	alias string
	url   string
	data  interface{}
}

// Config holds all runtime configuration
type Config struct {
	InputFiles        []string
	InputString       string
	InputDir          string
	OutputFile        string
	OutputDir         string
	Datasources       map[string]interface{}
	Templates         []string
