	DatasourceHeaders: make(map[string]string),
	Plugins:           make(map[string]string),
	Context:           make(map[string]interface{}),
}

func init() {
	rootCmd = &cobra.Command{
		Use:   "gomplate",
		Short: "Process text files with Go templates",
		RunE:  runGomplate,
