	rootCmd.Flags().StringVarP(&cfg.InputString, "in", "i", "", "Template string to process")
	rootCmd.Flags().StringVar(&cfg.InputDir, "input-dir", "", "Directory with templates")
	rootCmd.Flags().StringVarP(&cfg.OutputFile, "out", "o", "-", "Output file")
	rootCmd.Flags().StringVar(&cfg.OutputDir, "output-dir", ".", "Output directory for --input-dir")
	rootCmd.Flags().StringSliceVarP(&cfg.Templates, "template", "t", []string{}, "Additional templates")
	rootCmd.Flags().StringVar(&cfg.LeftDelim, "left-delim", "{{", "Left delimiter")
	rootCmd.Flags().StringVar(&cfg.RightDelim, "right-delim", "}}", "Right delimiter")
	rootCmd.Flags().StringVar(&cfg.MissingKey, "missing-key", "error", "Handle missing map keys")
	rootCmd.Flags().BoolVarP(&cfg.Verbose, "verbose", "V", false, "Verbose output")
	rootCmd.Flags().BoolVar(&cfg.ExecPipe, "exec-pipe", false, "Pipe output to exec")
	rootCmd.Flags().StringVar(&cfg.Chmod, "chmod", "", "Set output file mode")
	rootCmd.Flags().StringVar(&cfg.OutputMap, "output-map", "", "Map input to output path")
	rootCmd.Flags().StringSliceVar(&cfg.Exclude, "exclude", []string{}, "Exclude globs")
	rootCmd.Flags().StringSliceVar(&cfg.ExcludeProcessing, "exclude-processing", []string{}, "Exclude from processing")
	rootCmd.Flags().StringSliceVar(&cfg.Include, "include", []string{}, "Include globs")

	// Datasource flags
	datasources := []string{}
	rootCmd.Flags().StringSliceVarP(&datasources, "datasource", "d", []string{}, "Datasource alias=URL")

	// Context flag
	contexts := []string{}
	rootCmd.Flags().StringSliceVarP(&contexts, "context", "c", []string{}, "Context datasource")

	// Headers flag
	headers := []string{}
	rootCmd.Flags().StringSliceVarP(&headers, "datasource-header", "H", []string{}, "Datasource headers")

	// Plugins flag
	plugins := []string{}
	rootCmd.Flags().StringSliceVar(&plugins, "plugin", []string{}, "Plugins")

	// Store flags for post-processing
	rootCmd.RunE = func(cmd *cobra.Command, args []string) error {
		// Parse datasources
		for _, ds := range datasources {
			parts := strings.SplitN(ds, "=", 2)
			if len(parts) == 2 {
				cfg.Datasources[parts[0]] = parts[1]
			}
		}

		// Parse context
		for _, ctx := range contexts {
			parts := strings.SplitN(ctx, "=", 2)
			if len(parts) == 2 {
				cfg.Context[parts[0]] = parts[1]
			}
		}

		// Parse headers
		for _, h := range headers {
			parts := strings.SplitN(h, "=", 2)
			if len(parts) == 2 {
