func runGomplate(cmd *cobra.Command, args []string) error {
	// Handle version
	if v, _ := cmd.Flags().GetBool("version"); v {
		fmt.Printf("gomplate version %s\n", version)
		return nil
	}

	// Determine input source
	var input string
	var err error

	if cfg.InputString != "" {
		input = cfg.InputString
	} else if cfg.InputDir != "" {
		// Handle directory processing
		return processDirectory(cfg.InputDir, cfg.OutputDir)
	} else {
		// Read from file(s) or stdin
		var file *os.File
		if cfg.InputFiles[0] == "-" {
			file = os.Stdin
		} else {
			file, err = os.Open(cfg.InputFiles[0])
			if err != nil {
				return err
			}
			defer file.Close()
		}

		data, err := io.ReadAll(file)
		if err != nil {
			return err
		}
		input = string(data)
	}

	// Load datasources
	datasourceData := make(map[string]interface{})
	for alias, url := range cfg.Datasources {
		data, err := loadDataSource(url)
		if err != nil {
			return err
		}
		datasourceData[alias] = data
	}

	// Create template functions
	funcMap := createFuncMap(datasourceData)

	// Parse and execute template
	tmpl, err := template.New("tmpl").
		Delims(cfg.LeftDelim, cfg.RightDelim).
		Funcs(funcMap).
		Parse(input)
	if err != nil {
		return logError(err)
	}

	// Execute template
	var output bytes.Buffer
	err = tmpl.Execute(&output, map[string]interface{}{
		"Env": getEnvMap(),
	})
	if err != nil {
		return logError(err)
	}

	// Write output
	if cfg.OutputFile == "-" {
		fmt.Print(output.String())
	} else {
		err := os.WriteFile(cfg.OutputFile, output.Bytes(), 0644)
		if err != nil {
			return err
		}
	}

	return nil
}

func loadDataSource(url string) (interface{}, error) {
	// Try to load as file first
	data, err := os.ReadFile(url)
	if err == nil {
		// Parse based on extension
		if strings.HasSuffix(url, ".json") {
			var result interface{}
			if err := json.Unmarshal(data, &result); err != nil {
				return nil, err
			}
			return result, nil
		} else if strings.HasSuffix(url, ".yaml") || strings.HasSuffix(url, ".yml") {
			var result interface{}
			if err := yaml.Unmarshal(data, &result); err != nil {
				return nil, err
			}
			return result, nil
		}
		return string(data), nil
	}
	return nil, err
}

func getEnvMap() map[string]string {
	result := make(map[string]string)
	for _, e := range os.Environ() {
		parts := strings.SplitN(e, "=", 2)
		if len(parts) == 2 {
			result[parts[0]] = parts[1]
		}
	}
	return result
}

func createFuncMap(datasources map[string]interface{}) template.FuncMap {
	return template.FuncMap{
		// Math functions
		"add":      mathAdd,
		"mul":      mathMul,
		"sub":      mathSub,
		"div":      mathDiv,
		"abs":      mathAbs,
		"seq":      mathSeq,
		"ceil":     mathCeil,
		"floor":    mathFloor,
		"round":    mathRound,
		"pow":      mathPow,
		"sqrt":     mathSqrt,
		"max":      mathMax,
		"min":      mathMin,
		"rem":      mathRem,

		// Datasource function
		"ds": func(name string) interface{} {
			return datasources[name]
		},

		// Environment function
		"getenv": os.Getenv,

		// String functions
		"strings": func() interface{} {
			return stringFuncs{}
		},
	}
}

// Math function implementations
func mathAdd(args ...interface{}) int64 {
	result := int64(0)
	for _, arg := range args {
		result += toInt64(arg)
	}
	return result
}

func mathMul(args ...interface{}) int64 {
	result := int64(1)
	for _, arg := range args {
		result *= toInt64(arg)
	}
	return result
}

func mathSub(a, b interface{}) int64 {
	return toInt64(a) - toInt64(b)
}

func mathDiv(a, b interface{}) int64 {
	return toInt64(a) / toInt64(b)
}

func mathAbs(a interface{}) interface{} {
	switch v := a.(type) {
	case float64:
		return math.Abs(v)
	case float32:
		return float64(math.Abs(float64(v)))
	default:
		val := toInt64(a)
		if val < 0 {
			return -val
		}
		return val
	}
}

func mathSeq(start, end, step interface{}) []int64 {
	s := toInt64(start)
	e := toInt64(end)
	st := toInt64(step)

	if st == 0 {
		return []int64{}
	}

	// handle cases where step has wrong sign
	if e < s && st > 0 {
		st = -st
	}
	if e > s && st < 0 {
		st = -st
	}

	// adjust the end so it aligns exactly
	e -= (e - s) % st

	seq := []int64{s}
	last := s
	for last != e {
		last = seq[len(seq)-1] + st
		seq = append(seq, last)
	}
	return seq
}

func mathCeil(a interface{}) int64 {
	return int64(math.Ceil(toFloat64(a)))
