	}

	err = tmpl.Execute(&output, data)
	if err != nil {
		return logError(fmt.Sprintf("renderTemplate: failed to render template -: %v", err))
	}

	// Write output
	if cfg.OutputFile == "-" {
		fmt.Print(output.String())
	} else {
		err := os.WriteFile(cfg.OutputFile, output.Bytes(), 0644)
		if err != nil {
			return err
		}
	}

	return nil
}

func loadDataSource(url string) (interface{}, error) {
	data, err := os.ReadFile(url)
	if err != nil {
		return nil, err
	}

	if strings.HasSuffix(url, ".json") {
		var result interface{}
		if err := json.Unmarshal(data, &result); err != nil {
			return nil, err
		}
		return result, nil
	} else if strings.HasSuffix(url, ".yaml") || strings.HasSuffix(url, ".yml") {
		// Simple YAML parser for basic use cases
		result, err := parseYAML(data)
		if err != nil {
			return nil, err
		}
		return result, nil
	}

	return string(data), nil
}

// Simple YAML parser for basic cases
func parseYAML(data []byte) (interface{}, error) {
	lines := strings.Split(string(data), "\n")
	result := make(map[string]interface{})

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		parts := strings.SplitN(line, ":", 2)
		if len(parts) == 2 {
			key := strings.TrimSpace(parts[0])
			value := strings.TrimSpace(parts[1])

			// Try to parse as number
			if intVal, err := strconv.ParseInt(value, 10, 64); err == nil {
				result[key] = intVal
			} else if floatVal, err := strconv.ParseFloat(value, 64); err == nil {
				result[key] = floatVal
			} else {
				result[key] = value
			}
		}
	}

	return result, nil
}

func getEnvMap() map[string]string {
	result := make(map[string]string)
	for _, e := range os.Environ() {
		parts := strings.SplitN(e, "=", 2)
		if len(parts) == 2 {
			result[parts[0]] = parts[1]
		}
	}
	return result
}

func createFuncMap(datasources map[string]interface{}) template.FuncMap {
	return template.FuncMap{
		// Math functions
		"add":      mathAdd,
		"mul":      mathMul,
		"sub":      mathSub,
		"div":      mathDiv,
		"abs":      mathAbs,
		"seq":      mathSeq,
		"ceil":     mathCeil,
		"floor":    mathFloor,
		"round":    mathRound,
		"pow":      mathPow,
		"sqrt":     mathSqrt,
		"max":      mathMax,
		"min":      mathMin,
		"rem":      mathRem,

		// Datasource function
		"ds": func(name string) interface{} {
			return datasources[name]
		},

		// Environment function
		"getenv": os.Getenv,
	}
}

// Math functions
func mathAdd(args ...interface{}) int64 {
	result := int64(0)
	for _, arg := range args {
		result += toInt64(arg)
	}
	return result
}

func mathMul(args ...interface{}) int64 {
	result := int64(1)
	for _, arg := range args {
		result *= toInt64(arg)
	}
	return result
}

func mathSub(a, b interface{}) int64 {
	return toInt64(a) - toInt64(b)
}

func mathDiv(a, b interface{}) int64 {
	return toInt64(a) / toInt64(b)
}

func mathAbs(a interface{}) interface{} {
	f := toFloat64(a)
	if f == float64(int64(f)) {
		v := int64(f)
		if v < 0 {
			return -v
		}
		return v
	}
	return math.Abs(f)
}

func mathSeq(start, end, step interface{}) []int64 {
	s := toInt64(start)
	e := toInt64(end)
	st := toInt64(step)

	if st == 0 {
		return []int64{}
	}

	// handle cases where step has wrong sign
	if e < s && st > 0 {
		st = -st
	}
	if e > s && st < 0 {
		st = -st
	}

	// adjust the end so it aligns exactly
	e -= (e - s) % st

	seq := []int64{s}
	last := s
	for last != e {
		last = seq[len(seq)-1] + st
		seq = append(seq, last)
	}
	return seq
}

func mathCeil(a interface{}) int64 {
	return int64(math.Ceil(toFloat64(a)))
}

func mathFloor(a interface{}) int64 {
	return int64(math.Floor(toFloat64(a)))
}

func mathRound(a interface{}) int64 {
	return int64(math.Round(toFloat64(a)))
}

func mathPow(base, exp interface{}) float64 {
	return math.Pow(toFloat64(base), toFloat64(exp))
}

func mathSqrt(a interface{}) float64 {
	return math.Sqrt(toFloat64(a))
}

func mathMax(args ...interface{}) int64 {
	if len(args) == 0 {
		return 0
	}
	result := toInt64(args[0])
	for _, arg := range args[1:] {
		val := toInt64(arg)
		if val > result {
			result = val
		}
	}
	return result
}

func mathMin(args ...interface{}) int64 {
	if len(args) == 0 {
		return 0
	}
	result := toInt64(args[0])
	for _, arg := range args[1:] {
		val := toInt64(arg)
		if val < result {
			result = val
		}
	}
	return result
}

func mathRem(a, b interface{}) int64 {
	return toInt64(a) % toInt64(b)
}

// Helper functions
func toInt64(v interface{}) int64 {
	switch val := v.(type) {
	case int64:
		return val
	case int:
		return int64(val)
	case float64:
		return int64(val)
	case float32:
		return int64(val)
	case string:
		// Try parsing as int or float
		if strings.HasPrefix(val, "0x") || strings.HasPrefix(val, "0X") {
			i, _ := strconv.ParseInt(val, 16, 64)
			return i
		} else if strings.HasPrefix(val, "0") && len(val) > 1 && !strings.Contains(val, ".") {
			i, _ := strconv.ParseInt(val, 8, 64)
			return i
		}
		if f, err := strconv.ParseFloat(val, 64); err == nil {
			return int64(f)
		}
		return 0
	default:
		return 0
	}
}

func toFloat64(v interface{}) float64 {
	switch val := v.(type) {
	case float64:
		return val
	case float32:
		return float64(val)
	case int64:
		return float64(val)
	case int:
		return float64(val)
	case string:
		f, _ := strconv.ParseFloat(val, 64)
		return f
	default:
		return 0
	}
}

func logError(msg string) error {
	logEntry := map[string]interface{}{
		"time":  time.Now().UTC().Format(time.RFC3339Nano),
		"level": "ERROR",
		"msg":   "",
		"err":   msg,
	}
	jsonBytes, _ := json.Marshal(logEntry)
	fmt.Println(string(jsonBytes))
	return fmt.Errorf(msg)
}

